/**
 * empathy-templates.ts — 诊断共情模板
 *
 * 对标 Claw-Code recovery_recipes.rs 的场景化消息生成：
 *   - 按风险等级调整语气和措辞
 *   - 按接收者角色定制信息深度
 *   - 场景感知的坏消息传递策略
 *
 * 六种沟通场景：
 *   OPENING         — 诊断开场
 *   FINDING_SHARED  — 共识型发现（低风险）
 *   FINDING_SENSITIVE — 敏感发现（需谨慎措辞）
 *   CRITICAL_ALERT  — 关键风险预警
 *   RECOMMENDATION  — 行动建议
 *   CLOSING         — 诊断收尾
 */
/** 沟通场景 */
export type EmpathyScenario = 'opening' | 'finding_shared' | 'finding_sensitive' | 'critical_alert' | 'recommendation' | 'closing';
/** 接收者角色类型 */
export type RecipientRole = 'ceo' | 'cto' | 'manager' | 'ic' | 'hr';
/** 风险等级 */
export type RiskSeverity = 'low' | 'medium' | 'high' | 'critical';
/** 模板参数 */
export interface EmpathyTemplateParams {
    scenario: EmpathyScenario;
    recipientRole: RecipientRole;
    severity: RiskSeverity;
    /** 团队/组织名称 */
    teamName: string;
    /** 具体发现/维度名 */
    dimensionName?: string;
    /** 自定义插值变量 */
    variables?: Record<string, string>;
}
/** 消息块 */
export interface EmpathyMessage {
    /** 主要消息（显示在卡片顶部） */
    headline: string;
    /** 详细说明 */
    body: string;
    /** 建议的语气标记：direct | supportive | urgent | neutral */
    tone: 'direct' | 'supportive' | 'urgent' | 'neutral';
    /** 是否包含行动号召 */
    hasCallToAction: boolean;
}
/** 渲染共情消息 */
export declare function renderEmpathyMessage(params: EmpathyTemplateParams): EmpathyMessage;
/** 批量渲染：为一条发现生成面向多角色的消息 */
export declare function renderMultiRoleMessages(params: Omit<EmpathyTemplateParams, 'recipientRole'>, roles: RecipientRole[]): Map<RecipientRole, EmpathyMessage>;
/** 获取角色的推荐称呼 */
export declare function getRoleLabel(role: RecipientRole): string;
/** 获取角色的沟通风格参数 */
export declare function getRoleTone(role: RecipientRole): {
    formality: number;
    detailLevel: number;
};
/** 根据角色调整信息的详细程度 */
export declare function adaptDetailLevel(baseMessage: string, role: RecipientRole): string;
